INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('CRE.G6.CHRIST.SANCTITY_OF_LIFE.b', 'CRE.G6.CHRIST.SANCTITY_OF_LIFE', 'b', 'outline the effects of violating the right to life', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
