INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('CRE.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.a', 'CRE.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA', 'a', 'explain Christian teachings on the dangers of alcohol, drugs and substance abuse', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
