INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.CREATI.MY_PURPOSE.TALENTS', 'CRE.G6.CREATI.MY_PURPOSE', 'cre', 6, 'Know what Exodus 31:3 and Romans 12:4 teach about God-given talents and how to use them', ARRAY['CRE.G6.CREATI.MY_PURPOSE.a', 'CRE.G6.CREATI.MY_PURPOSE.b', 'CRE.G6.CREATI.MY_PURPOSE.c']::text[], 'Says that God filled Bezalel with the Spirit of God, with wisdom, understanding, knowledge and skill for craftwork (Exodus 31:3), that the body has many parts with different work (Romans 12:4), that talents are God''s gift to be used to serve others, and names values that grow a talent (practice, patience, discipline, humility). Does not say talents are only for showing off. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the verse says","where a talent comes from","a value that grows a talent"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.CREATI.MARRIAGE_AND_FAMILY.MARRIAGE_BIBLE', 'CRE.G6.CREATI.MARRIAGE_AND_FAMILY', 'cre', 6, 'Know the biblical teaching on marriage and family (Genesis 2:21-24)', ARRAY['CRE.G6.CREATI.MARRIAGE_AND_FAMILY.a']::text[], 'Says that God made the woman from the man''s rib while he slept, that the man said she was bone of his bones, and that a man leaves his father and mother, is joined to his wife and the two become one. Does not say the woman was made from dust. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the passage","what the verse says about leaving and joining","why marriage is for adults"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.CREATI.MARRIAGE_AND_FAMILY.EARLY_MARRIAGE', 'CRE.G6.CREATI.MARRIAGE_AND_FAMILY', 'cre', 6, 'Know the results of early marriage and the values that help avoid it', ARRAY['CRE.G6.CREATI.MARRIAGE_AND_FAMILY.b', 'CRE.G6.CREATI.MARRIAGE_AND_FAMILY.c', 'CRE.G6.CREATI.MARRIAGE_AND_FAMILY.d']::text[], 'Gives results of early marriage (leaving school, early pregnancy and its health risks, poverty, violence, losing childhood), says that in Kenya the law sets 18 as the age to marry, names values that help (patience, self-control, respect, responsibility, courage to say no) and who to tell (a parent, a teacher, the chief, a children''s officer, Childline Kenya 116). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a result of early marriage","a value that helps","who to tell"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.CREATI.LEISURE.LEISURE_REST', 'CRE.G6.CREATI.LEISURE', 'cre', 6, 'Know God''s rest (Genesis 2:1-3) and what the Bible says about idleness (1 Timothy 5:13)', ARRAY['CRE.G6.CREATI.LEISURE.a', 'CRE.G6.CREATI.LEISURE.b']::text[], 'Says that God finished his work, rested on the seventh day, blessed it and made it holy, that rest is a gift and not a sign of tiredness, and that 1 Timothy 5:13 warns against idleness that leads to gossip and meddling. Does not say that leisure means doing nothing. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what God did on the seventh day","why rest is good","what the verse warns"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.CREATI.LEISURE.LEISURE_USE', 'CRE.G6.CREATI.LEISURE', 'cre', 6, 'Tell good use of leisure time from misuse, with the values that help', ARRAY['CRE.G6.CREATI.LEISURE.c', 'CRE.G6.CREATI.LEISURE.d', 'CRE.G6.CREATI.LEISURE.e']::text[], 'Gives good uses of free time (play, sport, reading, helping at home, church activities, a hobby, visiting the sick), misuses by young people (drugs and alcohol, gambling, too much phone or television, idle gossip, bad company) and values for good use (self-control, responsibility, time management, honesty). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["good use or misuse","a value for leisure","what to do with free time"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.INSPIRED', 'CRE.G6.THE_BI.INSPIRED_WORD_OF_GOD', 'cre', 6, 'Know why the Bible is the inspired word of God (2 Timothy 3:16-17) and some of its authors', ARRAY['CRE.G6.THE_BI.INSPIRED_WORD_OF_GOD.a', 'CRE.G6.THE_BI.INSPIRED_WORD_OF_GOD.b']::text[], 'Says that all Scripture is God-breathed and useful for teaching, rebuking, correcting and training in righteousness (2 Timothy 3:16-17), that people wrote what God inspired, and names three authors (for example Moses, David, Paul). Does not say the Bible has one author. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what 2 Timothy 3:16-17 says","what inspired means","an author of a book of the Bible"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.TRANSLATION', 'CRE.G6.THE_BI.INSPIRED_WORD_OF_GOD', 'cre', 6, 'Know why the Bible was translated into local languages and its advantages', ARRAY['CRE.G6.THE_BI.INSPIRED_WORD_OF_GOD.c', 'CRE.G6.THE_BI.INSPIRED_WORD_OF_GOD.d', 'CRE.G6.THE_BI.INSPIRED_WORD_OF_GOD.e']::text[], 'Gives reasons for translating the Bible (so people can read and understand it in their own language, to spread the gospel, to keep the language alive, to read at home and in small groups) and advantages (better understanding, more people read it, it strengthens faith, it helps teaching), and does not say translation changes God''s message. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a reason for translation","an advantage of reading in your language","which statement is false"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_OUTLINE', 'CRE.G6.THE_BI.THE_TEN_COMMANDMENTS', 'cre', 6, 'Know what the Ten Commandments command (Exodus 20:3-17)', ARRAY['CRE.G6.THE_BI.THE_TEN_COMMANDMENTS.a']::text[], 'Says that the Ten Commandments (Exodus 20:3-17) call for no other gods, no idols, honouring God''s name, keeping a day of rest, honouring father and mother, and not killing, committing adultery, stealing, giving false witness or coveting; does not add laws from elsewhere (such as tithes) and does not number them. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which command is in the list","which is not","which command a situation breaks"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_VALUES', 'CRE.G6.THE_BI.THE_TEN_COMMANDMENTS', 'cre', 6, 'Name the values and lessons in the Ten Commandments', ARRAY['CRE.G6.THE_BI.THE_TEN_COMMANDMENTS.b', 'CRE.G6.THE_BI.THE_TEN_COMMANDMENTS.c', 'CRE.G6.THE_BI.THE_TEN_COMMANDMENTS.d']::text[], 'Links a command to the value it teaches (honouring parents: respect; not stealing: honesty; not giving false witness: truthfulness; not coveting: contentment; not killing: respect for life; a day of rest: self-control and worship) and says that the commands guide how we treat God and other people. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which value goes with a command","what a lesson from a command is","what a situation shows"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.SAMSON', 'CRE.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF', 'cre', 6, 'Know the story of Samson and the Philistines (Judges 15:14-17) and its lessons', ARRAY['CRE.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.a', 'CRE.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.b', 'CRE.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.c']::text[], 'Says that when the Philistines shouted at him the Spirit of the Lord came on Samson with power, the ropes on his arms fell off like burnt flax, that he took a fresh jawbone of a donkey and killed a thousand men, and that his strength came from the Lord. Gives lessons (depend on God, God gives strength for hard times). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","where his strength came from","a lesson from the story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_BI.FAITH_IN_GOD_ELISHA.ELISHA', 'CRE.G6.THE_BI.FAITH_IN_GOD_ELISHA', 'cre', 6, 'Know how Elisha recovered the axe head (2 Kings 6:1-7) and what it teaches about faith', ARRAY['CRE.G6.THE_BI.FAITH_IN_GOD_ELISHA.a', 'CRE.G6.THE_BI.FAITH_IN_GOD_ELISHA.b', 'CRE.G6.THE_BI.FAITH_IN_GOD_ELISHA.c']::text[], 'Says that the prophets were cutting trees by the Jordan, that the axe head fell into the water and was borrowed, that Elisha asked where it fell, cut a stick and threw it in, that the iron floated and the man picked it up. Gives lessons (take problems to God, God cares about small needs, faith). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what Elisha did","a lesson about faith"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.JACOB', 'CRE.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL', 'cre', 6, 'Know the story of Jacob wrestling (Genesis 32:22-30) and its lessons', ARRAY['CRE.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.a', 'CRE.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.b', 'CRE.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.c', 'CRE.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.d']::text[], 'Says that Jacob sent his family across the Jabbok and was left alone, that a man wrestled with him until daybreak, wrenched his hip, that Jacob said "I will not let you go unless you bless me", that his name was changed to Israel and he named the place Peniel. Gives lessons (persist in prayer, God blesses faith). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what Jacob asked","a lesson from the story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_LI.THE_CALL_OF_DISCIPLES.DISCIPLES', 'CRE.G6.THE_LI.THE_CALL_OF_DISCIPLES', 'cre', 6, 'Know the call of the first disciples (Mark 1:16-20) and how people are called today', ARRAY['CRE.G6.THE_LI.THE_CALL_OF_DISCIPLES.a', 'CRE.G6.THE_LI.THE_CALL_OF_DISCIPLES.b']::text[], 'Says that Jesus saw Simon and Andrew fishing and said "Follow me, and I will make you fishers of men", that they left their nets, that he called James and John who left their father Zebedee, and that people today are called in many ways (as teachers, nurses, pastors, parents, helpers). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the call","what Jesus said","how people are called today"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.TEMPTATIONS', 'CRE.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS', 'cre', 6, 'Know how Jesus was tempted in the wilderness (Luke 4:1-13) and how young people face temptation', ARRAY['CRE.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.a', 'CRE.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.b', 'CRE.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.c']::text[], 'Says that Jesus fasted forty days, that the devil tempted him to turn a stone to bread, to worship him for the kingdoms, and to throw himself from the temple, that Jesus answered each time with Scripture and did not give in, and names temptations young people meet (cheating, lying, bad company, drugs) and ways to resist (pray, use God''s word, ask for help). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a temptation","how Jesus answered","a temptation young people meet"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.ROMAN_OFFICER', 'CRE.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST', 'cre', 6, 'Know the healing of the Roman officer''s servant (Matthew 8:5-13) and its lessons', ARRAY['CRE.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.a', 'CRE.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.b', 'CRE.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.c']::text[], 'Says that a Roman officer in Capernaum asked Jesus to heal his paralysed servant, that he said he was not worthy to have Jesus come under his roof and that Jesus need only speak, that Jesus was amazed at his faith, and that the servant was healed at that hour. Gives lessons (faith, humility, care for others) and praying for the sick. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the healing","what the officer said","a lesson from the story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_LI.MIRACLE_OF_HEALING.BLEEDING_WOMAN', 'CRE.G6.THE_LI.MIRACLE_OF_HEALING', 'cre', 6, 'Know the healing of the bleeding woman (Luke 8:43-48) and how the church and government help the sick', ARRAY['CRE.G6.THE_LI.MIRACLE_OF_HEALING.a', 'CRE.G6.THE_LI.MIRACLE_OF_HEALING.b', 'CRE.G6.THE_LI.MIRACLE_OF_HEALING.c', 'CRE.G6.THE_LI.MIRACLE_OF_HEALING.d']::text[], 'Says that the woman had bled for twelve years and spent all she had on doctors, that she touched the edge of Jesus'' cloak and was healed at once, that Jesus asked who touched him and told her "Your faith has healed you", and names ways the church (hospitals and clinics, prayer, visiting) and the government (hospitals, clinics, vaccination, health insurance) help the sick. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the healing","what Jesus said to her","who helps the sick"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_LI.RAISING_LAZARUS_FROM_THE.LAZARUS_RAISED', 'CRE.G6.THE_LI.RAISING_LAZARUS_FROM_THE', 'cre', 6, 'Know the raising of Lazarus (John 11:32-45) and its lessons', ARRAY['CRE.G6.THE_LI.RAISING_LAZARUS_FROM_THE.a', 'CRE.G6.THE_LI.RAISING_LAZARUS_FROM_THE.b', 'CRE.G6.THE_LI.RAISING_LAZARUS_FROM_THE.c']::text[], 'Says that Mary fell at Jesus'' feet, that Jesus wept, that Lazarus had been in the tomb four days behind a stone, that Jesus prayed and called "Lazarus, come out!" and the dead man came out bound in cloth. Gives lessons (Jesus has power over death, Jesus cares, trust God in sorrow). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the miracle","what Jesus said and did","a lesson from the miracle"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_LI.THE_HIDDEN_TREASURE.HIDDEN_TREASURE', 'CRE.G6.THE_LI.THE_HIDDEN_TREASURE', 'cre', 6, 'Know the parable of the hidden treasure (Matthew 13:44) and what it teaches', ARRAY['CRE.G6.THE_LI.THE_HIDDEN_TREASURE.a', 'CRE.G6.THE_LI.THE_HIDDEN_TREASURE.b', 'CRE.G6.THE_LI.THE_HIDDEN_TREASURE.c']::text[], 'Says that a man found treasure hidden in a field, hid it again, and in his joy sold everything he had and bought the field, and that Jesus said the kingdom of heaven is like this. Gives the lesson (the kingdom of God is worth more than anything). Does not say the lesson is about getting rich. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the parable","what the treasure stands for","a lesson from the parable"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.RICH_MAN', 'CRE.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS', 'cre', 6, 'Know the parable of the rich man and Lazarus (Luke 16:19-31) and its lessons', ARRAY['CRE.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.a', 'CRE.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.b', 'CRE.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.c']::text[], 'Says that a rich man feasted every day while the beggar Lazarus lay at his gate covered with sores, that both died, that Lazarus was carried to Abraham and the rich man was in torment, that a great chasm lay between them, and that the rich man asked that his brothers be warned. Gives lessons (share with the poor, do not ignore need). Does not mix this Lazarus with the Lazarus of John 11. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the parable","what the rich man did wrong","a lesson from the parable"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_CH.APOSTLES_CREED.CREED_TEACHING', 'CRE.G6.THE_CH.APOSTLES_CREED', 'cre', 6, 'Know what the Apostles'' Creed says and why Christians say it', ARRAY['CRE.G6.THE_CH.APOSTLES_CREED.a', 'CRE.G6.THE_CH.APOSTLES_CREED.b', 'CRE.G6.THE_CH.APOSTLES_CREED.c']::text[], 'Says that the creed begins "I believe in God the Father Almighty, maker of heaven and earth", that it says Jesus Christ was born of the Virgin Mary, suffered under Pontius Pilate, was crucified, died and was buried, rose on the third day, ascended and will come to judge, that it also speaks of the Holy Spirit, the forgiveness of sins and life everlasting, and that Christians say it to affirm their faith. Does not say the creed is a book of the Bible. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the creed says","which line is not in the creed","why Christians say it"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_CH.APOSTLES_CREED.TRINITY', 'CRE.G6.THE_CH.APOSTLES_CREED', 'cre', 6, 'Name the three persons of the Holy Trinity and what each does', ARRAY['CRE.G6.THE_CH.APOSTLES_CREED.d', 'CRE.G6.THE_CH.APOSTLES_CREED.e']::text[], 'Names the Father, the Son and the Holy Spirit as the three persons of the Trinity (one God, not three gods), and links each with what the Bible says: the Father as creator, the Son as saviour, the Holy Spirit as helper and comforter. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the three persons","which person does what","which is false"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.PAUL_SUFFERING', 'CRE.G6.THE_CH.STANDING_FIRM_IN_FAITH_A', 'cre', 6, 'Know the suffering and virtues of Paul in 2 Corinthians 6:3-7 and how to stand firm', ARRAY['CRE.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.a', 'CRE.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.b', 'CRE.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.c']::text[], 'Lists what the apostles went through in 2 Corinthians 6:3-7 (troubles, hardships, distress, beatings, prison, riots, hard work, sleepless nights, hunger) and the virtues Paul showed (purity, understanding, patience, kindness, sincere love, truthful speech), and applies one to a situation. Does not say suffering means God is angry. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the apostles suffered","a virtue Paul showed","how to stand firm"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.THE_CH.CHURCH_UNITY.CHURCH_UNITY', 'CRE.G6.THE_CH.CHURCH_UNITY', 'cre', 6, 'Know what church unity is and what 1 Corinthians 12:12, Galatians 3:28 and Matthew 16:18 teach', ARRAY['CRE.G6.THE_CH.CHURCH_UNITY.a', 'CRE.G6.THE_CH.CHURCH_UNITY.b', 'CRE.G6.THE_CH.CHURCH_UNITY.c']::text[], 'Says that church unity is believers being one in Christ and working together in love; that 1 Corinthians 12:12 compares the church to one body with many parts, that Galatians 3:28 says all are one in Christ whatever their tribe, status or sex, and that Jesus said "I will build my church" (Matthew 16:18); and gives ways unity helps people live in peace. Does not say unity means everyone being the same. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what a verse teaches","what unity is","how unity helps"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.CHRIST.FRIENDSHIP_FORMATION.FRIENDSHIP', 'CRE.G6.CHRIST.FRIENDSHIP_FORMATION', 'cre', 6, 'Know why good friends matter and what 1 Corinthians 15:33 and Proverbs 13:20-21 and 16:28-29 teach', ARRAY['CRE.G6.CHRIST.FRIENDSHIP_FORMATION.a', 'CRE.G6.CHRIST.FRIENDSHIP_FORMATION.b', 'CRE.G6.CHRIST.FRIENDSHIP_FORMATION.c']::text[], 'Says that bad company corrupts good character (1 Corinthians 15:33), that the one who walks with the wise grows wise and the companion of fools suffers harm (Proverbs 13:20-21), that gossip and a violent person separate friends and lead others astray (Proverbs 16:28-29), and gives qualities of a good friend (honest, kind, respectful, helps you do right). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the verse says","a quality of a good friend","what to do about a friend who leads you astray"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_BIBLE', 'CRE.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON', 'cre', 6, 'Know the biblical teaching on responsible behaviour and respect for the body (James 1:14-16, 1 Corinthians 6:19)', ARRAY['CRE.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.a', 'CRE.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.d']::text[], 'Says that temptation begins when we are drawn by our own desire (James 1:14-16), that the Bible teaches self-control and waiting for marriage, that the body is the temple of the Holy Spirit (1 Corinthians 6:19) and should be respected, and does not say that being tempted is itself a sin. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the verse says","why the body is respected","what a responsible choice is"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_SKILLS', 'CRE.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON', 'cre', 6, 'Know the causes of irresponsible behaviour among youth and the values and life skills that help', ARRAY['CRE.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.b', 'CRE.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.c']::text[], 'Gives causes (peer pressure, harmful content on phones and television, idleness, poverty and gifts offered for favours, alcohol and drugs, too little guidance), and the values and life skills that help (self-control, assertiveness, decision-making, refusing and walking away, talking to a parent or trusted adult), and does not say that accepting gifts for favours is harmless. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a cause","a value or life skill that helps","what to do in a risky situation"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE', 'CRE.G6.CHRIST.SANCTITY_OF_LIFE', 'cre', 6, 'Know why life is sacred (Exodus 20:13, Matthew 5:21) and the virtues that protect it', ARRAY['CRE.G6.CHRIST.SANCTITY_OF_LIFE.a', 'CRE.G6.CHRIST.SANCTITY_OF_LIFE.b', 'CRE.G6.CHRIST.SANCTITY_OF_LIFE.c', 'CRE.G6.CHRIST.SANCTITY_OF_LIFE.d']::text[], 'Says that life is a gift from God, that Exodus 20:13 says "You shall not murder" and Jesus taught that anger and hatred also harm (Matthew 5:21-22), names practices that violate the right to life (murder, mob justice, child abuse and neglect, drink-driving, harmful bullying), their effects (grief, orphans, broken families, prison) and virtues that protect life (love, forgiveness, patience, respect, self-control). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what a verse teaches","which practice violates life","an effect","a virtue that protects life"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE', 'CRE.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA', 'cre', 6, 'Know the Christian teaching on alcohol, drugs and substance abuse and the dangers', ARRAY['CRE.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.a', 'CRE.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.d']::text[], 'Says that Ephesians 5:18 tells Christians not to get drunk but to be filled with the Spirit and Hosea 4:11 says wine takes away understanding, names substances young people misuse (alcohol, bhang, miraa, cigarettes, glue, petrol), tells misuse from medicine taken as a health worker directs, and gives dangers (poor health, failing school, quarrels, crime, addiction). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the verse says","which is a misused substance","a danger of misuse"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_PREVENT', 'CRE.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA', 'cre', 6, 'Know how Christians and the government prevent drug abuse, and how to say no', ARRAY['CRE.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.b', 'CRE.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.c', 'CRE.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.d']::text[], 'Names Christian strategies (prayer, counselling, church youth programmes, caring for those who struggle, rehabilitation), names what government agencies do (NACADA campaigns against alcohol and drug abuse, the police and courts act against traffickers, laws control drugs), and gives ways a child says no (refuse firmly, walk away, give a reason, tell an adult). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a strategy","what an agency does","how to say no"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
