INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE', 'CRES.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS', 'skill', 'essential', 'Grade 5: drugs abused, why young people start and the effects. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE', 'CRES.G4.CHRIST.HOLINESS.HOLINESS', 'skill', 'essential', 'The body as a temple, which drugs harm. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_PREVENT', 'CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE', 'skill', 'essential', 'The teaching and the dangers come before prevention. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_PREVENT', 'CRES.G5.CHRIST.FRIENDSHIP_FORMATION.FRIENDS', 'skill', 'essential', 'Resisting a friend''s bad influence. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MY_PURPOSE.TALENTS.M_TAL6_SOURCE', 'CRES.G6.CREATI.MY_PURPOSE.TALENTS', 'Says talents come from luck or from oneself alone.', '{"question":"Where do talents and abilities come from?","wrong_answer":"From luck","correct_answer":"From God"}'::jsonb, 'The child has heard people called "lucky" to be gifted.', 'Offer "From luck" beside "From God" and ask the child to choose.', 'Read Exodus 31:3: God filled Bezalel with skill. Ask the child to name a gift and say who gave it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MY_PURPOSE.TALENTS.M_TAL6_SHOW', 'CRES.G6.CREATI.MY_PURPOSE.TALENTS', 'Says a talent is for showing off or for oneself only.', '{"question":"What are talents given for?","wrong_answer":"To show off","correct_answer":"To serve others"}'::jsonb, 'Talent shows on TV reward the best performer, so a talent looks like a prize to display.', 'Offer "To show off" beside "To serve others" and ask the child to choose.', 'Link 1 Peter 4:10 with Romans 12:4: each part of the body works for the whole. Ask how a singer serves the church.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MY_PURPOSE.TALENTS.M_TAL6_VERSE', 'CRES.G6.CREATI.MY_PURPOSE.TALENTS', 'Mixes what Exodus 31:3 and Romans 12:4 say.', '{"question":"Which verse says the body has many parts with different work?","wrong_answer":"Exodus 31:3","correct_answer":"Romans 12:4"}'::jsonb, 'Both verses are learnt in one lesson and the references blur.', 'Offer "Exodus 31:3" beside "Romans 12:4" and ask the child to choose.', 'Give each verse a picture: Exodus 31:3, a craftsman; Romans 12:4, a body with many parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MY_PURPOSE.TALENTS.M_C6_TAL_ONLY_SCHOOL', 'CRES.G6.CREATI.MY_PURPOSE.TALENTS', 'Thinks only talents that earn marks or money count, so singing, kindness or craft are not talents.', '{"question":"Which of these is a God-given talent?","wrong_answer":"Only being top in exams","correct_answer":"Any gift, such as singing, drawing, farming, kindness or leading"}'::jsonb, 'School rewards marks most, so the child ranks other gifts lower.', 'Offer "Only being top in exams" beside "Any gift, such as singing, drawing, farming, kindness or leading" and ask the child to choose.', 'List gifts in the class; Bezalel''s gift was craftwork (Exodus 31:3). Every gift serves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MARRIAGE_AND_FAMILY.MARRIAGE_BIBLE.M_MAR6_ORIGIN', 'CRES.G6.CREATI.MARRIAGE_AND_FAMILY.MARRIAGE_BIBLE', 'Says God made the woman from dust or from clay.', '{"question":"What did God use to make the woman (Genesis 2:21-22)?","wrong_answer":"The dust of the ground","correct_answer":"A rib taken from the man"}'::jsonb, 'The child knows the man was made from dust (Genesis 2:7) and gives the woman the same origin.', 'Offer "The dust of the ground" beside "A rib taken from the man" and ask the child to choose.', 'Put Genesis 2:7 and 2:21-22 side by side: the man from dust, the woman from the man''s rib.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MARRIAGE_AND_FAMILY.MARRIAGE_BIBLE.M_MAR6_LEAVE', 'CRES.G6.CREATI.MARRIAGE_AND_FAMILY.MARRIAGE_BIBLE', 'Says a man stays in his parents'' home when he marries.', '{"question":"What does Genesis 2:24 say a man does when he marries?","wrong_answer":"He stays with his parents","correct_answer":"He leaves his father and mother and is joined to his wife"}'::jsonb, 'In many homes a son''s family lives near his parents, so the child reads leaving as wrong.', 'Offer "He stays with his parents" beside "He leaves his father and mother and is joined to his wife" and ask the child to choose.', 'Explain that "leave" means a new household and first loyalty to the spouse, while still honouring parents.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MARRIAGE_AND_FAMILY.MARRIAGE_BIBLE.M_MAR6_SLEEP', 'CRES.G6.CREATI.MARRIAGE_AND_FAMILY.MARRIAGE_BIBLE', 'Mixes the details of the sleep and the rib.', '{"question":"What did God do before he took the rib?","wrong_answer":"He woke the man","correct_answer":"He put the man into a deep sleep"}'::jsonb, 'The child retells from memory and puts the events in the order of an operation he imagines.', 'Offer "He woke the man" beside "He put the man into a deep sleep" and ask the child to choose.', 'Read 2:21 aloud and number the events: deep sleep, rib taken, flesh closed, woman made.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MARRIAGE_AND_FAMILY.EARLY_MARRIAGE.M_EM6_BENEFIT', 'CRES.G6.CREATI.MARRIAGE_AND_FAMILY.EARLY_MARRIAGE', 'Thinks early marriage helps a girl or her family.', '{"question":"What is a result of early marriage for a girl?","wrong_answer":"She has a better future","correct_answer":"She may leave school and face health risks"}'::jsonb, 'The child has heard that marriage brings a girl security or the family dowry.', 'Offer "She has a better future" beside "She may leave school and face health risks" and ask the child to choose.', 'List what a girl loses (school, health, choice) against what is promised; read the 18-year rule.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MARRIAGE_AND_FAMILY.EARLY_MARRIAGE.M_EM6_RIGHT', 'CRES.G6.CREATI.MARRIAGE_AND_FAMILY.EARLY_MARRIAGE', 'Says a person may marry at 14 in Kenya, taking a custom some have heard of as the law, instead of 18.', '{"question":"In Kenya at what age may a person marry?","wrong_answer":"14 years","correct_answer":"18 years"}'::jsonb, 'Some communities have married girls young and the child takes custom as law.', 'Offer "14 years" beside "18 years" and ask the child to choose.', 'Say clearly: in Kenya the law sets 18. Ask what the law protects.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MARRIAGE_AND_FAMILY.EARLY_MARRIAGE.M_EM6_KEEP_QUIET', 'CRES.G6.CREATI.MARRIAGE_AND_FAMILY.EARLY_MARRIAGE', 'Thinks a child at risk should keep quiet.', '{"question":"A girl is told she will be married next month. What should she do?","wrong_answer":"Keep quiet to respect her elders","correct_answer":"Tell a teacher, the chief or Childline 116"}'::jsonb, 'Respect for elders is taught strongly, so speaking up feels like disobedience.', 'Offer "Keep quiet to respect her elders" beside "Tell a teacher, the chief or Childline 116" and ask the child to choose.', 'Explain that telling a teacher or the chief is how a child stays safe and is not disrespect. Name Childline 116.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MARRIAGE_AND_FAMILY.MARRIAGE_BIBLE.M_C6_MAR_ADAM_NAMED', 'CRES.G6.CREATI.MARRIAGE_AND_FAMILY.MARRIAGE_BIBLE', 'Thinks God named the woman, when the man said "she shall be called woman" (Genesis 2:23).', '{"question":"Who said \"she shall be called woman\" (Genesis 2:23)?","wrong_answer":"God","correct_answer":"The man"}'::jsonb, 'God does most of the speaking in Genesis 1-2, so the child gives God this line too.', 'Offer "God" beside "The man" and ask the child to choose.', 'Read 2:23 and ask who is speaking: "bone of my bones". It is the man.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.MARRIAGE_AND_FAMILY.EARLY_MARRIAGE.M_C6_EM_BOYS_FINE', 'CRES.G6.CREATI.MARRIAGE_AND_FAMILY.EARLY_MARRIAGE', 'Thinks early marriage is a problem only for girls and that a boy marrying young is fine.', '{"question":"Is early marriage harmful for boys too?","wrong_answer":"No, only for girls","correct_answer":"Yes: boys also leave school and take on burdens too early"}'::jsonb, 'Most stories the child hears are of girls married young.', 'Offer "No, only for girls" beside "Yes: boys also leave school and take on burdens too early" and ask the child to choose.', 'List results for a boy: leaves school, must provide too early, poverty. The law is 18 for both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.LEISURE.LEISURE_REST.M_LEI6_TIRED', 'CRES.G6.CREATI.LEISURE.LEISURE_REST', 'Says God rested because he was tired.', '{"question":"Why did God rest on the seventh day (Genesis 2:2-3)?","wrong_answer":"He was tired","correct_answer":"He had finished his work, and he blessed the day and made it holy"}'::jsonb, 'People rest when tired, so the child gives God the same reason.', 'Offer "He was tired" beside "He had finished his work, and he blessed the day and made it holy" and ask the child to choose.', 'Read Genesis 2:2-3: God finished, blessed and made holy. Ask whether God gets tired (Isaiah 40:28).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.LEISURE.LEISURE_REST.M_LEI6_IDLE', 'CRES.G6.CREATI.LEISURE.LEISURE_REST', 'Says leisure means doing nothing.', '{"question":"What does 1 Timothy 5:13 warn against?","wrong_answer":"Resting at all","correct_answer":"Idleness that leads to gossip and meddling"}'::jsonb, 'The child hears "leisure" as free time with nothing in it.', 'Offer "Resting at all" beside "Idleness that leads to gossip and meddling" and ask the child to choose.', 'Contrast rest that refreshes with idleness that leads to gossip (1 Timothy 5:13).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.LEISURE.LEISURE_REST.M_LEI6_DAY', 'CRES.G6.CREATI.LEISURE.LEISURE_REST', 'Says God rested on the sixth day, the day people were made, instead of the seventh.', '{"question":"On which day did God rest (Genesis 2:2)?","wrong_answer":"The sixth day","correct_answer":"The seventh day"}'::jsonb, 'The sixth day is when people were made, and the child joins the last thing made with the rest.', 'Offer "The sixth day" beside "The seventh day" and ask the child to choose.', 'Count the days on the fingers: six of creating, the seventh of rest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.LEISURE.LEISURE_USE.M_LEI6_MISUSE', 'CRES.G6.CREATI.LEISURE.LEISURE_USE', 'Thinks drugs, gambling or too much phone time are fine ways to use free time.', '{"question":"Which is a good use of free time?","wrong_answer":"Gambling with friends","correct_answer":"Reading or helping at home"}'::jsonb, 'Free time is time "for me", so the child thinks anything goes.', 'Offer "Gambling with friends" beside "Reading or helping at home" and ask the child to choose.', 'Sort cards into builds up and pulls down, and name the harm of each misuse.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.LEISURE.LEISURE_USE.M_LEI6_NO_LIMIT', 'CRES.G6.CREATI.LEISURE.LEISURE_USE', 'Thinks free time has no limits or no value.', '{"question":"Which value helps a youth use leisure well?","wrong_answer":"Doing whatever pleases the group","correct_answer":"Self-control"}'::jsonb, 'The group decides what is fun, and the child follows it.', 'Offer "Doing whatever pleases the group" beside "Self-control" and ask the child to choose.', 'Name values: self-control, responsibility, time management. Ask what each looks like on a Saturday.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.LEISURE.LEISURE_REST.M_C6_LEI_SABBATH_LAZY', 'CRES.G6.CREATI.LEISURE.LEISURE_REST', 'Thinks God''s rest means God stopped caring for the world after creation.', '{"question":"After God rested on the seventh day, did he stop caring for the world?","wrong_answer":"Yes, he left the world alone","correct_answer":"No: he finished creating, and he still cares for his world"}'::jsonb, 'The child pictures rest as switching off.', 'Offer "Yes, he left the world alone" beside "No: he finished creating, and he still cares for his world" and ask the child to choose.', 'Read Psalm 121:4: he who watches over Israel will neither slumber nor sleep. God rested from creating, not from caring.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.LEISURE.LEISURE_USE.M_C6_LEI_PHONE_ALL_DAY', 'CRES.G6.CREATI.LEISURE.LEISURE_USE', 'Thinks spending a whole holiday on a phone or TV is a good use of leisure because it is not harmful.', '{"question":"Halima spends every day of the holiday on her phone from morning to night. Is this good use of leisure?","wrong_answer":"Yes, it is harmless","correct_answer":"No: it wastes time and crowds out rest, chores, family and reading"}'::jsonb, 'Screen time is not named as a sin, so the child thinks it is fine in any amount.', 'Offer "Yes, it is harmless" beside "No: it wastes time and crowds out rest, chores, family and reading" and ask the child to choose.', 'Draw a day as a pie: sleep, chores, family, play, reading, screen. What happens if screen fills it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CREATI.LEISURE.LEISURE_USE.M_C6_LEI_ONLY_PLAY', 'CRES.G6.CREATI.LEISURE.LEISURE_USE', 'Thinks only play counts as leisure, not reading, hobbies, church activities or helping others.', '{"question":"Which of these is a good use of leisure?","wrong_answer":"Only playing games","correct_answer":"Reading, a hobby, sport, visiting the sick or a church activity"}'::jsonb, 'The child knows leisure only as play time.', 'Offer "Only playing games" beside "Reading, a hobby, sport, visiting the sick or a church activity" and ask the child to choose.', 'List leisure activities in four groups: rest, play, learn, serve. All can be good.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.INSPIRED.M_INS6_ONE', 'CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.INSPIRED', 'Says the Bible has one author.', '{"question":"How many authors does the Bible have?","wrong_answer":"One person wrote all of it","correct_answer":"Many people wrote it, inspired by God"}'::jsonb, 'The Bible is one book with one cover, so the child expects one writer.', 'Offer "One person wrote all of it" beside "Many people wrote it, inspired by God" and ask the child to choose.', 'Show the contents page: many books, written over many years by many writers, all inspired by God.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.INSPIRED.M_INS6_HUMAN', 'CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.INSPIRED', 'Thinks the Bible is only the ideas of wise men, missing that 2 Timothy 3:16 calls Scripture God-breathed.', '{"question":"What does 2 Timothy 3:16 say about Scripture?","wrong_answer":"It is only the ideas of wise men","correct_answer":"It is God-breathed"}'::jsonb, 'The child knows people wrote the Bible and stops there.', 'Offer "It is only the ideas of wise men" beside "It is God-breathed" and ask the child to choose.', 'Read 2 Timothy 3:16: "God-breathed". People wrote, God inspired.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.INSPIRED.M_INS6_USE', 'CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.INSPIRED', 'Gives winning arguments or making money as a use of Scripture, instead of teaching, correcting and training in righteousness.', '{"question":"What is Scripture useful for (2 Timothy 3:16)?","wrong_answer":"Winning arguments and making money","correct_answer":"Teaching, correcting and training in righteousness"}'::jsonb, 'The child has seen verses quoted to win an argument.', 'Offer "Winning arguments and making money" beside "Teaching, correcting and training in righteousness" and ask the child to choose.', 'Read 2 Timothy 3:16-17 and list its four uses: teaching, rebuking, correcting, training in righteousness.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.TRANSLATION.M_TRA6_CHANGE', 'CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.TRANSLATION', 'Says translation changes God''s message.', '{"question":"Does translating the Bible change its message?","wrong_answer":"Yes, it makes a new message","correct_answer":"No, it puts the same message into another language"}'::jsonb, 'The child has seen poor translations or mistranslated signs.', 'Offer "Yes, it makes a new message" beside "No, it puts the same message into another language" and ask the child to choose.', 'Show one verse in English, Kiswahili and a local language: same meaning, different words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.TRANSLATION.M_TRA6_ENGLISH', 'CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.TRANSLATION', 'Thinks there is no need to translate because English is enough for everyone.', '{"question":"Why translate the Bible into local languages?","wrong_answer":"There is no need: English is enough for everyone","correct_answer":"So people can understand it in their own language"}'::jsonb, 'The child has heard English treated as the "proper" language of church and school.', 'Offer "There is no need: English is enough for everyone" beside "So people can understand it in their own language" and ask the child to choose.', 'Ask: if a grandmother reads only Dholuo, how will she hear God''s word? Translation lets everyone understand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.TRANSLATION.M_TRA6_COST', 'CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.TRANSLATION', 'Thinks translation makes the Bible shorter, instead of making it understood by more people.', '{"question":"Which is an advantage of reading the Bible in your own language?","wrong_answer":"It makes the Bible shorter","correct_answer":"You understand it better and more people can read it"}'::jsonb, 'The child links translation with making things simpler or shorter.', 'Offer "It makes the Bible shorter" beside "You understand it better and more people can read it" and ask the child to choose.', 'List real advantages: understanding, more readers, the message reaches homes, faith grows in one''s own language.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.INSPIRED.M_C6_INS_AUTHORS_WRONG', 'CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.INSPIRED', 'Names Jesus or Abraham as a writer of Bible books.', '{"question":"Which of these wrote books of the Bible?","wrong_answer":"Jesus and Abraham","correct_answer":"Moses, David and Paul"}'::jsonb, 'The child names the people most spoken of in the Bible.', 'Offer "Jesus and Abraham" beside "Moses, David and Paul" and ask the child to choose.', 'Match writers to books: Moses (the Law, by tradition), David (many Psalms), Paul (letters). Jesus'' words were written down by the Gospel writers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.TRANSLATION.M_C6_TRA_NEW_BOOKS', 'CRES.G6.THE_BI.INSPIRED_WORD_OF_GOD.TRANSLATION', 'Thinks translators add new books or stories for their own people.', '{"question":"When the Bible is translated into Kikuyu, what happens to its books?","wrong_answer":"New Kikuyu stories are added","correct_answer":"The same books are put into Kikuyu"}'::jsonb, 'The child imagines a translated Bible as a new edition for that people.', 'Offer "New Kikuyu stories are added" beside "The same books are put into Kikuyu" and ask the child to choose.', 'Compare contents pages of an English and a Kiswahili Bible: the same books in the same order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_OUTLINE.M_TEN6_OTHER_LAW', 'CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_OUTLINE', 'Adds a law from another part of the Bible (such as tithes) to the Ten Commandments.', '{"question":"Which is one of the Ten Commandments?","wrong_answer":"Give a tenth of your harvest","correct_answer":"Honour your father and your mother"}'::jsonb, 'The tithe is a well-known Old Testament law and the child joins it to the famous ten.', 'Offer "Give a tenth of your harvest" beside "Honour your father and your mother" and ask the child to choose.', 'Read Exodus 20:3-17 and tick each command; the tithe is not there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_OUTLINE.M_TEN6_INVENTED', 'CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_OUTLINE', 'Picks "you shall not steal", which is a commandment, as one that is not, and misses that praying three times a day is not among the ten.', '{"question":"Which is not in the Ten Commandments?","wrong_answer":"You shall not steal","correct_answer":"Pray three times a day"}'::jsonb, 'The child confuses church practices with the commandments.', 'Offer "You shall not steal" beside "Pray three times a day" and ask the child to choose.', 'Make a list from the passage and check any statement against it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_OUTLINE.M_TEN6_WRONG_MATCH', 'CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_OUTLINE', 'Says taking a pen that is not yours breaks "do not give false witness" instead of "do not steal".', '{"question":"Otieno takes a pen that is not his. Which command does that break?","wrong_answer":"You shall not give false witness","correct_answer":"You shall not steal"}'::jsonb, 'Stealing and lying are both "bad" and the child picks the first wrong he remembers.', 'Offer "You shall not give false witness" beside "You shall not steal" and ask the child to choose.', 'Match situation cards to command cards, one at a time, reading the command aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_VALUES.M_TEN6_VALUE', 'CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_VALUES', 'Links a command to the wrong value.', '{"question":"Which value does \"honour your father and your mother\" teach?","wrong_answer":"Honesty","correct_answer":"Respect"}'::jsonb, 'Honour and honesty sound alike and both are taught as good values.', 'Offer "Honesty" beside "Respect" and ask the child to choose.', 'Write each command with its value: honour parents, respect; do not lie, honesty; do not steal, honesty and contentment.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_VALUES.M_TEN6_RELIGIOUS_ONLY', 'CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_VALUES', 'Thinks the commands are only about worship.', '{"question":"The Ten Commandments guide how we treat...","wrong_answer":"God only","correct_answer":"God and other people"}'::jsonb, 'The commands are taught in RE, so the child thinks they are only about worship.', 'Offer "God only" beside "God and other people" and ask the child to choose.', 'Sort the commands on two tablets: God and people. Most are about how we treat others.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_OUTLINE.M_C6_TEN_WHERE', 'CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_OUTLINE', 'Thinks the Ten Commandments were given to Abraham or by Jesus.', '{"question":"To whom did God give the Ten Commandments?","wrong_answer":"To Abraham","correct_answer":"To Moses, for Israel, at Mount Sinai"}'::jsonb, 'The child places all early laws with Abraham, the father of the nation.', 'Offer "To Abraham" beside "To Moses, for Israel, at Mount Sinai" and ask the child to choose.', 'Read Exodus 19:20 and 20:1: God spoke on Mount Sinai and gave the law through Moses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_VALUES.M_C6_TEN_COVET', 'CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_VALUES', 'Thinks coveting is the same as admiring, so it cannot be wrong.', '{"question":"Juma wants his classmate''s new bag so much that he plans to take it. Which command warns about this?","wrong_answer":"None: wanting is never wrong","correct_answer":"You shall not covet"}'::jsonb, 'The word covet is new and the child thinks wishing cannot be a sin.', 'Offer "None: wanting is never wrong" beside "You shall not covet" and ask the child to choose.', 'Explain covet: wanting what is someone else''s so much that it rules you. Contrast with admiring and being content.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_VALUES.M_C6_TEN_OLD_ONLY', 'CRES.G6.THE_BI.THE_TEN_COMMANDMENTS.TEN_VALUES', 'Thinks the Ten Commandments were only for Israel long ago and teach nothing today.', '{"question":"Do the Ten Commandments teach anything for today?","wrong_answer":"No, they were only for long ago","correct_answer":"Yes: values such as respect, honesty and faithfulness still guide us"}'::jsonb, 'The child hears "Old Testament" as "out of date".', 'Offer "No, they were only for long ago" beside "Yes: values such as respect, honesty and faithfulness still guide us" and ask the child to choose.', 'Read Matthew 22:37-39: Jesus sums up the law as loving God and neighbour. Match each command to today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.SAMSON.M_SAM6_OWN', 'CRES.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.SAMSON', 'Says Samson''s strength came from himself.', '{"question":"What gave Samson power against the Philistines (Judges 15:14)?","wrong_answer":"His own muscles","correct_answer":"The Spirit of the Lord came on him"}'::jsonb, 'Samson is pictured as a strongman, so the child gives him the credit.', 'Offer "His own muscles" beside "The Spirit of the Lord came on him" and ask the child to choose.', 'Read Judges 15:14: "the Spirit of the Lord came powerfully upon him". Compare with Judges 14:6 in Grade 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.SAMSON.M_SAM6_WEAPON', 'CRES.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.SAMSON', 'Says Samson used a sword instead of the fresh jawbone of a donkey.', '{"question":"What did Samson use to strike the Philistines (Judges 15:15)?","wrong_answer":"A sword","correct_answer":"The jawbone of a donkey"}'::jsonb, 'Soldiers in stories fight with swords, so the child fills that in.', 'Offer "A sword" beside "The jawbone of a donkey" and ask the child to choose.', 'Read 15:15 and show a picture of a jawbone: God used something weak and ordinary.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.SAMSON.M_SAM6_NUMBER', 'CRES.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.SAMSON', 'Says Samson killed a hundred men, instead of a thousand.', '{"question":"How many men did Samson kill with it (Judges 15:15)?","wrong_answer":"One hundred","correct_answer":"One thousand"}'::jsonb, 'Large numbers blur, and the child picks a round number he knows.', 'Offer "One hundred" beside "One thousand" and ask the child to choose.', 'Read 15:16 where Samson himself says "a thousand men".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.SAMSON.M_C6_SAM_ROPES', 'CRES.G6.THE_BI.BIBLE_STORIES_SAMSON_DEF.SAMSON', 'Thinks Samson broke free by cutting the ropes with a knife.', '{"question":"How did the ropes on Samson''s arms come off (Judges 15:14)?","wrong_answer":"He cut them with a knife","correct_answer":"They became like burnt flax and fell off when the Spirit came on him"}'::jsonb, 'The child explains the escape by an ordinary tool.', 'Offer "He cut them with a knife" beside "They became like burnt flax and fell off when the Spirit came on him" and ask the child to choose.', 'Read 15:14 and act burnt thread falling apart. God freed him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.FAITH_IN_GOD_ELISHA.ELISHA.M_ELI6_SWIM', 'CRES.G6.THE_BI.FAITH_IN_GOD_ELISHA.ELISHA', 'Says Elisha dived to get the axe head.', '{"question":"How was the axe head recovered (2 Kings 6:6)?","wrong_answer":"Elisha dived in and found it","correct_answer":"Elisha threw in a stick and the iron floated"}'::jsonb, 'The child explains the recovery as something a strong man could do.', 'Offer "Elisha dived in and found it" beside "Elisha threw in a stick and the iron floated" and ask the child to choose.', 'Read 2 Kings 6:6: Elisha threw a stick and the iron floated. Iron sinks; only God could make it float.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.FAITH_IN_GOD_ELISHA.ELISHA.M_ELI6_OWNER', 'CRES.G6.THE_BI.FAITH_IN_GOD_ELISHA.ELISHA', 'Says the axe was Elisha''s, missing that a prophet had borrowed it.', '{"question":"Whose axe head fell into the water (2 Kings 6:5)?","wrong_answer":"Elisha''s","correct_answer":"A prophet''s who had borrowed it"}'::jsonb, 'Elisha is the main character, so the child gives him the axe.', 'Offer "Elisha''s" beside "A prophet''s who had borrowed it" and ask the child to choose.', 'Read 6:5: "It was borrowed!" The worry was a poor prophet''s debt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.FAITH_IN_GOD_ELISHA.ELISHA.M_ELI6_SMALL', 'CRES.G6.THE_BI.FAITH_IN_GOD_ELISHA.ELISHA', 'Thinks God cares only about big problems.', '{"question":"What does the story teach about small problems?","wrong_answer":"God cares only about big problems","correct_answer":"We can take even small needs to God"}'::jsonb, 'The child thinks God is too great to care about a lost tool.', 'Offer "God cares only about big problems" beside "We can take even small needs to God" and ask the child to choose.', 'Ask: why did the man cry out? A borrowed axe was a big worry for him. God cared.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.FAITH_IN_GOD_ELISHA.ELISHA.M_C6_ELI_RIVER', 'CRES.G6.THE_BI.FAITH_IN_GOD_ELISHA.ELISHA', 'Places the axe-head story at the sea or Lake Galilee instead of the River Jordan.', '{"question":"Where were the prophets cutting trees when the axe head fell (2 Kings 6:2-4)?","wrong_answer":"At the Sea of Galilee","correct_answer":"By the River Jordan"}'::jsonb, 'Water miracles of Jesus happen at the lake, so the child places this one there too.', 'Offer "At the Sea of Galilee" beside "By the River Jordan" and ask the child to choose.', 'Read 6:2 and 6:4: they went to the Jordan. Mark it on a map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.JACOB.M_JAC6_WON', 'CRES.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.JACOB', 'Says Jacob won by being stronger.', '{"question":"Why was Jacob blessed (Genesis 32:26-29)?","wrong_answer":"He was stronger than the man","correct_answer":"He held on and asked for a blessing"}'::jsonb, 'A wrestling match is won by strength, so the child reads the story as a sports contest.', 'Offer "He was stronger than the man" beside "He held on and asked for a blessing" and ask the child to choose.', 'Read 32:25-26: the man touched his hip and Jacob still held on asking for a blessing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.JACOB.M_JAC6_NAME', 'CRES.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.JACOB', 'Gives Isaac, Jacob''s father, as Jacob''s new name instead of Israel.', '{"question":"What new name did Jacob receive (Genesis 32:28)?","wrong_answer":"Isaac","correct_answer":"Israel"}'::jsonb, 'Isaac is Jacob''s father and the family names blur.', 'Offer "Isaac" beside "Israel" and ask the child to choose.', 'Draw the family line: Abraham, Isaac, Jacob, then "Israel", Jacob''s new name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.JACOB.M_JAC6_PLACE', 'CRES.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.JACOB', 'Says Jacob''s family crossed the Jordan instead of the ford of the Jabbok.', '{"question":"Which river did Jacob''s family cross (Genesis 32:22)?","wrong_answer":"The Jordan","correct_answer":"The Jabbok"}'::jsonb, 'The Jordan is the river the child knows best.', 'Offer "The Jordan" beside "The Jabbok" and ask the child to choose.', 'Read 32:22: the ford of the Jabbok. Write the name twice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.JACOB.M_C6_JAC_HIP', 'CRES.G6.THE_BI.JACOB_WRESTLES_AN_ANGEL.JACOB', 'Thinks Jacob came away unhurt.', '{"question":"What happened to Jacob''s hip (Genesis 32:25, 31)?","wrong_answer":"Nothing happened to it","correct_answer":"It was put out of joint and he limped"}'::jsonb, 'The child expects the blessed one to leave unharmed.', 'Offer "Nothing happened to it" beside "It was put out of joint and he limped" and ask the child to choose.', 'Read 32:31: he was limping because of his hip. He held on even when hurt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_CALL_OF_DISCIPLES.DISCIPLES.M_DIS6_JOB', 'CRES.G6.THE_LI.THE_CALL_OF_DISCIPLES.DISCIPLES', 'Says Simon and Andrew were collecting taxes, mixing them with Matthew, instead of casting a net into the lake.', '{"question":"What were Simon and Andrew doing when Jesus called them (Mark 1:16)?","wrong_answer":"Collecting taxes","correct_answer":"Casting a net into the sea"}'::jsonb, 'Matthew the tax collector is another famous call story and the jobs swap.', 'Offer "Collecting taxes" beside "Casting a net into the sea" and ask the child to choose.', 'Make two cards: Simon and Andrew, fishermen; Matthew, tax collector.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_CALL_OF_DISCIPLES.DISCIPLES.M_DIS6_WORDS', 'CRES.G6.THE_LI.THE_CALL_OF_DISCIPLES.DISCIPLES', 'Gives "Come and rest" as Jesus'' words to Simon and Andrew instead of "Follow me, and I will make you fishers of people".', '{"question":"What did Jesus say to Simon and Andrew?","wrong_answer":"\"Come and rest\"","correct_answer":"\"Follow me, and I will make you fishers of men\""}'::jsonb, 'The child knows "come to me and rest" (Matthew 11:28) and swaps the verses.', 'Offer ""Come and rest"" beside ""Follow me, and I will make you fishers of men"" and ask the child to choose.', 'Read Mark 1:17: "fishers of people". Ask why fishermen would understand this.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_CALL_OF_DISCIPLES.DISCIPLES.M_DIS6_ONLY_CLERGY', 'CRES.G6.THE_LI.THE_CALL_OF_DISCIPLES.DISCIPLES', 'Thinks only pastors are called.', '{"question":"Who is called to serve God today?","wrong_answer":"Only pastors and priests","correct_answer":"People in many kinds of work and roles"}'::jsonb, 'Calling is spoken of mostly at ordinations.', 'Offer "Only pastors and priests" beside "People in many kinds of work and roles" and ask the child to choose.', 'List people who serve God in work: a nurse, a teacher, a farmer, a choir member.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_CALL_OF_DISCIPLES.DISCIPLES.M_C6_DIS_DELAYED', 'CRES.G6.THE_LI.THE_CALL_OF_DISCIPLES.DISCIPLES', 'Thinks the first disciples finished their work and went home before following Jesus.', '{"question":"What did Simon and Andrew do when Jesus called them (Mark 1:18)?","wrong_answer":"Finished fishing and followed later","correct_answer":"At once they left their nets and followed him"}'::jsonb, 'The child expects sensible people to finish their job first.', 'Offer "Finished fishing and followed later" beside "At once they left their nets and followed him" and ask the child to choose.', 'Read Mark 1:18 and 1:20 and underline "at once" and "without delay".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.TEMPTATIONS.M_TEM6_GAVE_IN', 'CRES.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.TEMPTATIONS', 'Says Jesus gave in to one temptation.', '{"question":"How did Jesus respond to the devil (Luke 4:1-13)?","wrong_answer":"He gave in to the second temptation","correct_answer":"He answered each time with Scripture and did not give in"}'::jsonb, 'The child thinks being tempted three times means one must have worked.', 'Offer "He gave in to the second temptation" beside "He answered each time with Scripture and did not give in" and ask the child to choose.', 'Read each answer of Jesus with its "It is written"; he never gave in.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.TEMPTATIONS.M_TEM6_FIRST', 'CRES.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.TEMPTATIONS', 'Says the first temptation was to jump from the temple instead of turning a stone into bread.', '{"question":"What was the first temptation (Luke 4:3)?","wrong_answer":"To jump from the temple","correct_answer":"To turn a stone into bread"}'::jsonb, 'Matthew and Luke give the temptations in a different order, and the temple one is vivid.', 'Offer "To jump from the temple" beside "To turn a stone into bread" and ask the child to choose.', 'Number Luke 4:3, 4:5 and 4:9 on the board: bread first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.TEMPTATIONS.M_TEM6_ALONE', 'CRES.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.TEMPTATIONS', 'Thinks a young person should face temptation alone.', '{"question":"What can a young person do when tempted to cheat?","wrong_answer":"Give in so as not to look weak","correct_answer":"Pray, remember God''s word and ask a trusted adult"}'::jsonb, 'The child fears looking weak and thinks asking for help shows weakness.', 'Offer "Give in so as not to look weak" beside "Pray, remember God''s word and ask a trusted adult" and ask the child to choose.', 'Show Jesus used God''s word; a young person can use God''s word, prayer and a trusted adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.TEMPTATIONS.M_C6_TEM_SCRIPTURE_ANSWER', 'CRES.G6.THE_LI.THE_TEMPTATIONS_OF_JESUS.TEMPTATIONS', 'Thinks Jesus beat the devil by arguing cleverly or by a miracle, not by quoting Scripture.', '{"question":"How did Jesus answer each temptation in Luke 4?","wrong_answer":"By doing a miracle to scare the devil","correct_answer":"By quoting God''s word: \"It is written\""}'::jsonb, 'The child expects the Son of God to use power.', 'Offer "By doing a miracle to scare the devil" beside "By quoting God''s word: "It is written"" and ask the child to choose.', 'Underline "It is written" three times in Luke 4:4, 8 and 12. A child can learn verses too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.ROMAN_OFFICER.M_ROM6_WHO', 'CRES.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.ROMAN_OFFICER', 'Says the sick one was the officer''s son or daughter.', '{"question":"Who was sick in Matthew 8:6?","wrong_answer":"His son","correct_answer":"His servant"}'::jsonb, 'Jairus asked for his daughter, and the child mixes the two requests.', 'Offer "His son" beside "His servant" and ask the child to choose.', 'Read Matthew 8:6: "my servant". Ask why an officer would care so much for a servant.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.ROMAN_OFFICER.M_ROM6_WENT', 'CRES.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.ROMAN_OFFICER', 'Says Jesus went to the house to heal.', '{"question":"How was the servant healed (Matthew 8:8-13)?","wrong_answer":"Jesus went to the house and laid hands on him","correct_answer":"Jesus spoke the word and he was healed at that hour"}'::jsonb, 'In other healings Jesus touches people, so the child adds a visit.', 'Offer "Jesus went to the house and laid hands on him" beside "Jesus spoke the word and he was healed at that hour" and ask the child to choose.', 'Read 8:8 and 8:13: "just say the word"; healed at that hour, far away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.ROMAN_OFFICER.M_ROM6_FAITH', 'CRES.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.ROMAN_OFFICER', 'Says Jesus rebuked the officer.', '{"question":"What did Jesus say about the officer''s faith?","wrong_answer":"It was too small","correct_answer":"He had not found such great faith in Israel"}'::jsonb, 'Jesus often corrects people''s small faith, and the child expects the same here.', 'Offer "It was too small" beside "He had not found such great faith in Israel" and ask the child to choose.', 'Read 8:10: Jesus was amazed: no one in Israel had such great faith.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.ROMAN_OFFICER.M_C6_ROM_JEW', 'CRES.G6.THE_LI.MIRACLES_OF_JESUS_CHRIST.ROMAN_OFFICER', 'Thinks the officer was a Jewish priest.', '{"question":"Who was the man who asked Jesus to heal his servant (Matthew 8:5)?","wrong_answer":"A Jewish priest","correct_answer":"A Roman officer (a centurion)"}'::jsonb, 'Most people asking Jesus for help are Jews, so the child assumes it.', 'Offer "A Jewish priest" beside "A Roman officer (a centurion)" and ask the child to choose.', 'Read 8:5 and 8:10: a Roman soldier, an outsider, had greater faith than many in Israel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.MIRACLE_OF_HEALING.BLEEDING_WOMAN.M_BLE6_DOCTORS', 'CRES.G6.THE_LI.MIRACLE_OF_HEALING.BLEEDING_WOMAN', 'Says the doctors healed the woman.', '{"question":"Who healed the bleeding woman (Luke 8:43-48)?","wrong_answer":"The doctors","correct_answer":"Jesus, when she touched his cloak in faith"}'::jsonb, 'The child knows doctors heal and gives them the credit.', 'Offer "The doctors" beside "Jesus, when she touched his cloak in faith" and ask the child to choose.', 'Read Luke 8:43: no one could heal her. Then 8:44: she touched his cloak and was healed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.MIRACLE_OF_HEALING.BLEEDING_WOMAN.M_BLE6_YEARS', 'CRES.G6.THE_LI.MIRACLE_OF_HEALING.BLEEDING_WOMAN', 'Says the woman had been bleeding for seven years instead of twelve.', '{"question":"For how long had she been bleeding (Luke 8:43)?","wrong_answer":"Seven years","correct_answer":"Twelve years"}'::jsonb, 'Seven is a common Bible number and the child picks it.', 'Offer "Seven years" beside "Twelve years" and ask the child to choose.', 'Link the number with Jairus'' daughter, who was twelve years old (Luke 8:42): both twelves are in one passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.MIRACLE_OF_HEALING.BLEEDING_WOMAN.M_BLE6_WORDS', 'CRES.G6.THE_LI.MIRACLE_OF_HEALING.BLEEDING_WOMAN', 'Thinks Jesus told her she was not worthy, instead of "Daughter, your faith has healed you; go in peace".', '{"question":"What did Jesus tell her (Luke 8:48)?","wrong_answer":"\"You are not worthy\"","correct_answer":"\"Daughter, your faith has healed you; go in peace\""}'::jsonb, 'The child knows she was "unclean" and expects Jesus to send her away.', 'Offer ""You are not worthy"" beside ""Daughter, your faith has healed you; go in peace"" and ask the child to choose.', 'Read 8:48: "Daughter". Jesus called her family.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.MIRACLE_OF_HEALING.BLEEDING_WOMAN.M_BLE6_HELP', 'CRES.G6.THE_LI.MIRACLE_OF_HEALING.BLEEDING_WOMAN', 'Says only the church helps the sick, forgetting government hospitals and clinics.', '{"question":"Who helps the sick today?","wrong_answer":"Only the church","correct_answer":"Both the church and the government, with hospitals and clinics"}'::jsonb, 'The lesson is in church, so the child names only the church.', 'Offer "Only the church" beside "Both the church and the government, with hospitals and clinics" and ask the child to choose.', 'List hospitals: government (county hospitals) and church (mission hospitals). Both help the sick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.MIRACLE_OF_HEALING.BLEEDING_WOMAN.M_C6_BLE_HIDDEN', 'CRES.G6.THE_LI.MIRACLE_OF_HEALING.BLEEDING_WOMAN', 'Thinks the woman slipped away unseen after she was healed.', '{"question":"What did the woman do when Jesus asked who touched him (Luke 8:47)?","wrong_answer":"Slipped away unseen","correct_answer":"Came trembling, fell at his feet and told everyone why"}'::jsonb, 'The child knows she came secretly and expects her to leave secretly.', 'Offer "Slipped away unseen" beside "Came trembling, fell at his feet and told everyone why" and ask the child to choose.', 'Read 8:47: she could not go unnoticed; she told everything, and Jesus blessed her.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.RAISING_LAZARUS_FROM_THE.LAZARUS_RAISED.M_LAZ6_WEPT', 'CRES.G6.THE_LI.RAISING_LAZARUS_FROM_THE.LAZARUS_RAISED', 'Thinks Jesus was angry with Mary and did not weep, missing "Jesus wept" (John 11:35).', '{"question":"What did Jesus do when he saw Mary weeping (John 11:35)?","wrong_answer":"He was angry with her","correct_answer":"Jesus wept"}'::jsonb, 'The child does not expect the Son of God to cry.', 'Offer "He was angry with her" beside "Jesus wept" and ask the child to choose.', 'Read John 11:35-36: Jesus wept and the people said "See how he loved him".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.RAISING_LAZARUS_FROM_THE.LAZARUS_RAISED.M_LAZ6_DAYS', 'CRES.G6.THE_LI.RAISING_LAZARUS_FROM_THE.LAZARUS_RAISED', 'Says Lazarus had been in the tomb one day instead of four.', '{"question":"For how many days had Lazarus been in the tomb (John 11:39)?","wrong_answer":"One day","correct_answer":"Four days"}'::jsonb, 'Jesus rose on the third day, and the child links "days in the tomb" with that.', 'Offer "One day" beside "Four days" and ask the child to choose.', 'Read 11:39: Martha said four days and a bad smell. He was truly dead.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.RAISING_LAZARUS_FROM_THE.LAZARUS_RAISED.M_LAZ6_WORDS', 'CRES.G6.THE_LI.RAISING_LAZARUS_FROM_THE.LAZARUS_RAISED', 'Gives "wake up and eat" as Jesus'' words at the tomb instead of "Lazarus, come out!"', '{"question":"What did Jesus call out at the tomb (John 11:43)?","wrong_answer":"\"Lazarus, wake up and eat\"","correct_answer":"\"Lazarus, come out!\""}'::jsonb, 'The child softens death to sleep and expects gentle words.', 'Offer ""Lazarus, wake up and eat"" beside ""Lazarus, come out!"" and ask the child to choose.', 'Read 11:43 loudly: "Lazarus, come out!"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.RAISING_LAZARUS_FROM_THE.LAZARUS_RAISED.M_C6_LAZ_SISTERS', 'CRES.G6.THE_LI.RAISING_LAZARUS_FROM_THE.LAZARUS_RAISED', 'Names Mary and Martha as Lazarus'' daughters or friends, not his sisters.', '{"question":"Who were Mary and Martha to Lazarus (John 11:1-2)?","wrong_answer":"His daughters","correct_answer":"His sisters"}'::jsonb, 'The child reads "Lord, the one you love is sick" and loses the family link.', 'Offer "His daughters" beside "His sisters" and ask the child to choose.', 'Read John 11:1-2 and draw the family: Lazarus with his sisters Mary and Martha at Bethany.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_HIDDEN_TREASURE.HIDDEN_TREASURE.M_HID6_RICH', 'CRES.G6.THE_LI.THE_HIDDEN_TREASURE.HIDDEN_TREASURE', 'Says the parable is about getting rich.', '{"question":"What is the lesson of the hidden treasure (Matthew 13:44)?","wrong_answer":"How to get rich quickly","correct_answer":"The kingdom of heaven is worth more than everything else"}'::jsonb, 'The child stays with the picture of treasure and misses that it stands for the kingdom.', 'Offer "How to get rich quickly" beside "The kingdom of heaven is worth more than everything else" and ask the child to choose.', 'Begin with Jesus'' words: "The kingdom of heaven is like". Ask what is worth more than everything.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_HIDDEN_TREASURE.HIDDEN_TREASURE.M_HID6_KEEP', 'CRES.G6.THE_LI.THE_HIDDEN_TREASURE.HIDDEN_TREASURE', 'Says the man kept everything he had.', '{"question":"What did the man do after finding the treasure?","wrong_answer":"He kept what he had and took the treasure","correct_answer":"He sold all he had and bought the field"}'::jsonb, 'The child thinks a wise man keeps what he has.', 'Offer "He kept what he had and took the treasure" beside "He sold all he had and bought the field" and ask the child to choose.', 'Read 13:44: "in his joy he sold all he had". Ask why selling everything was a joy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_HIDDEN_TREASURE.HIDDEN_TREASURE.M_HID6_PLACE', 'CRES.G6.THE_LI.THE_HIDDEN_TREASURE.HIDDEN_TREASURE', 'Says the treasure was hidden in a house instead of a field.', '{"question":"Where was the treasure hidden (Matthew 13:44)?","wrong_answer":"In a house","correct_answer":"In a field"}'::jsonb, 'Treasure in stories is kept in houses or boxes.', 'Offer "In a house" beside "In a field" and ask the child to choose.', 'Read 13:44 and draw a field with the treasure underground.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_HIDDEN_TREASURE.HIDDEN_TREASURE.M_C6_HID_STEAL', 'CRES.G6.THE_LI.THE_HIDDEN_TREASURE.HIDDEN_TREASURE', 'Thinks the man in the parable stole the treasure.', '{"question":"How did the man get the treasure (Matthew 13:44)?","wrong_answer":"He dug it up and ran away with it","correct_answer":"He sold all he had and bought the field"}'::jsonb, 'Finding treasure in someone else''s land sounds like stealing.', 'Offer "He dug it up and ran away with it" beside "He sold all he had and bought the field" and ask the child to choose.', 'Read 13:44: he bought the field. Jesus'' point is how much it was worth to him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.RICH_MAN.M_RIC6_WEALTH', 'CRES.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.RICH_MAN', 'Says the rich man was punished only for being rich.', '{"question":"Why was the rich man in torment (Luke 16:19-25)?","wrong_answer":"Only because he was rich","correct_answer":"Because he ignored the beggar at his gate"}'::jsonb, 'The child hears the rich man punished and concludes riches are the sin.', 'Offer "Only because he was rich" beside "Because he ignored the beggar at his gate" and ask the child to choose.', 'Read 16:19-21: Lazarus lay at his gate daily, hungry. The sin was ignoring him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.RICH_MAN.M_RIC6_SAME', 'CRES.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.RICH_MAN', 'Mixes this Lazarus with the Lazarus raised in John 11.', '{"question":"Which Lazarus lay at the rich man''s gate?","wrong_answer":"The brother of Mary and Martha","correct_answer":"A beggar in a parable of Jesus"}'::jsonb, 'Two Lazaruses appear in the Gospels and the child joins them.', 'Offer "The brother of Mary and Martha" beside "A beggar in a parable of Jesus" and ask the child to choose.', 'Make two cards: Lazarus of Bethany (John 11, real man raised); Lazarus the beggar (Luke 16, a parable).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.RICH_MAN.M_RIC6_CHASM', 'CRES.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.RICH_MAN', 'Says a river lay between the rich man and Lazarus, instead of a great chasm.', '{"question":"What lay between the rich man and Lazarus (Luke 16:26)?","wrong_answer":"A river","correct_answer":"A great chasm"}'::jsonb, 'The child pictures the afterlife with a river, from songs.', 'Offer "A river" beside "A great chasm" and ask the child to choose.', 'Read 16:26: a great chasm. Ask what it means that no one could cross.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.RICH_MAN.M_C6_RIC_SEND_LAZARUS', 'CRES.G6.THE_LI.THE_RICH_MAN_AND_LAZARUS.RICH_MAN', 'Thinks Abraham agreed to send Lazarus to warn the rich man''s brothers.', '{"question":"What did Abraham answer when asked to send Lazarus to the five brothers (Luke 16:29)?","wrong_answer":"He agreed and sent him","correct_answer":"\"They have Moses and the Prophets; let them listen to them\""}'::jsonb, 'The child expects a kind request to be granted.', 'Offer "He agreed and sent him" beside ""They have Moses and the Prophets; let them listen to them"" and ask the child to choose.', 'Read 16:29-31: the brothers already had God''s word. The lesson: listen now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.APOSTLES_CREED.CREED_TEACHING.M_CRE6_OTHER', 'CRES.G6.THE_CH.APOSTLES_CREED.CREED_TEACHING', 'Thinks "he was born in Rome" is a line of the creed, instead of "born of the Virgin Mary".', '{"question":"Which line is in the Apostles'' Creed?","wrong_answer":"He was born in Rome","correct_answer":"Born of the Virgin Mary"}'::jsonb, 'The child adds facts about Jesus that sound right but are not in the creed.', 'Offer "He was born in Rome" beside "Born of the Virgin Mary" and ask the child to choose.', 'Read the creed slowly and tick lines on a card. Only what is written there is in it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.APOSTLES_CREED.CREED_TEACHING.M_CRE6_BIBLE', 'CRES.G6.THE_CH.APOSTLES_CREED.CREED_TEACHING', 'Says the creed is a book of the Bible.', '{"question":"What is the Apostles'' Creed?","wrong_answer":"A book of the Bible","correct_answer":"A statement of Christian belief"}'::jsonb, 'The creed is said in church like Bible readings, so the child thinks it is one.', 'Offer "A book of the Bible" beside "A statement of Christian belief" and ask the child to choose.', 'Show that the creed is not in the contents page; it sums up what the Bible teaches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.APOSTLES_CREED.CREED_TEACHING.M_CRE6_ORDER', 'CRES.G6.THE_CH.APOSTLES_CREED.CREED_TEACHING', 'Mixes who creates and who judges.', '{"question":"Who does the creed call maker of heaven and earth?","wrong_answer":"Jesus Christ","correct_answer":"God the Father Almighty"}'::jsonb, 'The child knows Jesus is Lord and gives him the first line.', 'Offer "Jesus Christ" beside "God the Father Almighty" and ask the child to choose.', 'Draw three parts: Father (maker), Son (Jesus, born, died, rose, will judge), Holy Spirit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.APOSTLES_CREED.TRINITY.M_TRI6_THREE_GODS', 'CRES.G6.THE_CH.APOSTLES_CREED.TRINITY', 'Says the Trinity is three gods.', '{"question":"The Holy Trinity is...","wrong_answer":"Three different gods","correct_answer":"One God in three persons"}'::jsonb, 'Three names sound like three separate beings.', 'Offer "Three different gods" beside "One God in three persons" and ask the child to choose.', 'Read Deuteronomy 6:4 ("the Lord is one") and Matthew 28:19 (one name, three persons). Say: one God in three persons.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.APOSTLES_CREED.TRINITY.M_TRI6_MEMBER', 'CRES.G6.THE_CH.APOSTLES_CREED.TRINITY', 'Names the archangel Michael as the third person of the Trinity instead of the Holy Spirit.', '{"question":"Which is the third person of the Holy Trinity?","wrong_answer":"The archangel Michael","correct_answer":"The Holy Spirit"}'::jsonb, 'Angels are heavenly beings and the child counts one in.', 'Offer "The archangel Michael" beside "The Holy Spirit" and ask the child to choose.', 'Point to the baptism of Jesus: Father''s voice, the Son, the Spirit as a dove. No angel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.APOSTLES_CREED.TRINITY.M_TRI6_ROLE', 'CRES.G6.THE_CH.APOSTLES_CREED.TRINITY', 'Mixes what each person does.', '{"question":"Who is called the creator, in the creed?","wrong_answer":"The Holy Spirit","correct_answer":"God the Father"}'::jsonb, 'The Holy Spirit is linked with creation in Genesis 1:2, and the creed''s order blurs.', 'Offer "The Holy Spirit" beside "God the Father" and ask the child to choose.', 'Follow the creed''s lines: "God the Father Almighty, maker of heaven and earth".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.APOSTLES_CREED.CREED_TEACHING.M_C6_CRE_PILATE', 'CRES.G6.THE_CH.APOSTLES_CREED.CREED_TEACHING', 'Says the creed names King Herod, the king of the Christmas story, as the ruler under whom Jesus suffered, instead of Pontius Pilate.', '{"question":"Under whom does the creed say Jesus suffered?","wrong_answer":"King Herod","correct_answer":"Pontius Pilate"}'::jsonb, 'Herod is the king in the Christmas story.', 'Offer "King Herod" beside "Pontius Pilate" and ask the child to choose.', 'Read the line "suffered under Pontius Pilate" and link it to the Gospel accounts of the trial.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.APOSTLES_CREED.TRINITY.M_C6_TRI_SON_LATER', 'CRES.G6.THE_CH.APOSTLES_CREED.TRINITY', 'Thinks the Son is a lesser god, made by the Father.', '{"question":"Is Jesus, the Son, less God than the Father?","wrong_answer":"Yes, he is a smaller god","correct_answer":"No: Father, Son and Holy Spirit are one God"}'::jsonb, 'Son sounds younger and smaller than Father.', 'Offer "Yes, he is a smaller god" beside "No: Father, Son and Holy Spirit are one God" and ask the child to choose.', 'Read John 10:30: "I and the Father are one". Keep the words one God, three persons.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.PAUL_SUFFERING.M_PAU6_PUNISH', 'CRES.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.PAUL_SUFFERING', 'Says the apostles suffered because God was angry.', '{"question":"Why did the apostles suffer (2 Corinthians 6:3-7)?","wrong_answer":"God was angry with them","correct_answer":"They served Christ and were not stopped by hardship"}'::jsonb, 'The child thinks suffering always means God is angry.', 'Offer "God was angry with them" beside "They served Christ and were not stopped by hardship" and ask the child to choose.', 'Read 2 Corinthians 6:4: "as servants of God we commend ourselves in great endurance". They suffered for serving.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.PAUL_SUFFERING.M_PAU6_LIST', 'CRES.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.PAUL_SUFFERING', 'Names something that is not in the list of hardships.', '{"question":"Which is in Paul''s list of hardships?","wrong_answer":"Wealth and comfort","correct_answer":"Beatings and imprisonment"}'::jsonb, 'The child thinks an apostle''s life must have been comfortable.', 'Offer "Wealth and comfort" beside "Beatings and imprisonment" and ask the child to choose.', 'Read 6:4-5 and list the hardships on the board: troubles, beatings, prisons, riots, hunger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.PAUL_SUFFERING.M_PAU6_VIRTUE', 'CRES.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.PAUL_SUFFERING', 'Names a quality that is not one of Paul''s virtues.', '{"question":"Which virtue does Paul name (2 Corinthians 6:6)?","wrong_answer":"Pride","correct_answer":"Patience and kindness"}'::jsonb, 'The child picks any strong word as a virtue.', 'Offer "Pride" beside "Patience and kindness" and ask the child to choose.', 'Read 6:6 and list the virtues: purity, understanding, patience, kindness, sincere love.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.PAUL_SUFFERING.M_C6_PAU_GAVE_UP', 'CRES.G6.THE_CH.STANDING_FIRM_IN_FAITH_A.PAUL_SUFFERING', 'Thinks Paul stopped preaching after he was beaten and imprisoned.', '{"question":"What did Paul do after beatings and prisons (2 Corinthians 6:4-7)?","wrong_answer":"He stopped preaching","correct_answer":"He kept serving with patience, kindness and the power of God"}'::jsonb, 'The child expects that hardship makes people quit.', 'Offer "He stopped preaching" beside "He kept serving with patience, kindness and the power of God" and ask the child to choose.', 'Read 6:4-7 as one long sentence: all these hardships, and still patience, kindness, truthful speech.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.CHURCH_UNITY.CHURCH_UNITY.M_UNI6_SAME', 'CRES.G6.THE_CH.CHURCH_UNITY.CHURCH_UNITY', 'Says unity means everyone is the same.', '{"question":"What does unity in the church mean?","wrong_answer":"Everyone is exactly the same","correct_answer":"Different people working together as one in Christ"}'::jsonb, 'The child thinks unity means uniformity, like a uniform.', 'Offer "Everyone is exactly the same" beside "Different people working together as one in Christ" and ask the child to choose.', 'Read 1 Corinthians 12:12: one body, many parts. A body needs different parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.CHURCH_UNITY.CHURCH_UNITY.M_UNI6_BUILDING', 'CRES.G6.THE_CH.CHURCH_UNITY.CHURCH_UNITY', 'Thinks Jesus said "I will build my hall", picturing a building, instead of "my church", the people.', '{"question":"In Matthew 16:18 Jesus says \"I will build my...\"","wrong_answer":"Hall","correct_answer":"Church"}'::jsonb, 'The child knows "church" mostly as the building.', 'Offer "Hall" beside "Church" and ask the child to choose.', 'Read Matthew 16:18 and ask: can a building be built on a person''s faith? The church is the people.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.CHURCH_UNITY.CHURCH_UNITY.M_UNI6_RANK', 'CRES.G6.THE_CH.CHURCH_UNITY.CHURCH_UNITY', 'Thinks some people are more important in Christ.', '{"question":"What does Galatians 3:28 say about tribe or status?","wrong_answer":"Some are more important than others","correct_answer":"All are one in Christ Jesus"}'::jsonb, 'The child sees rank at school and in society and expects it in church.', 'Offer "Some are more important than others" beside "All are one in Christ Jesus" and ask the child to choose.', 'Read Galatians 3:28 and list groups: tribe, rich and poor, men and women: all one in Christ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.THE_CH.CHURCH_UNITY.CHURCH_UNITY.M_C6_UNI_DENOMINATION', 'CRES.G6.THE_CH.CHURCH_UNITY.CHURCH_UNITY', 'Thinks Christians of other churches are not part of the church of Christ.', '{"question":"Are Christians in a different church from yours part of the body of Christ?","wrong_answer":"No, only my church is","correct_answer":"Yes: all who follow Christ are one body"}'::jsonb, 'The child hears his own church named often and others rarely.', 'Offer "No, only my church is" beside "Yes: all who follow Christ are one body" and ask the child to choose.', 'Read 1 Corinthians 12:12-13: one body. Name churches in the area and say what they share.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.FRIENDSHIP_FORMATION.FRIENDSHIP.M_FRI6_POPULAR', 'CRES.G6.CHRIST.FRIENDSHIP_FORMATION.FRIENDSHIP', 'Chooses friends by popularity or wealth.', '{"question":"What makes a good friend?","wrong_answer":"Being popular and rich","correct_answer":"Being honest, kind and helping you do right"}'::jsonb, 'Popular children seem to have the best life, so the child wants to be near them.', 'Offer "Being popular and rich" beside "Being honest, kind and helping you do right" and ask the child to choose.', 'List qualities from Proverbs 13:20: walk with the wise. Ask what a friend helps you become.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.FRIENDSHIP_FORMATION.FRIENDSHIP.M_FRI6_BAD', 'CRES.G6.CHRIST.FRIENDSHIP_FORMATION.FRIENDSHIP', 'Thinks bad company cannot change you.', '{"question":"What does 1 Corinthians 15:33 say?","wrong_answer":"Bad company does not change a person","correct_answer":"Bad company corrupts good character"}'::jsonb, 'The child trusts himself to stay good in any company.', 'Offer "Bad company does not change a person" beside "Bad company corrupts good character" and ask the child to choose.', 'Read 1 Corinthians 15:33 and give an example: a friend who swears, and soon you swear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.FRIENDSHIP_FORMATION.FRIENDSHIP.M_FRI6_GOSSIP', 'CRES.G6.CHRIST.FRIENDSHIP_FORMATION.FRIENDSHIP', 'Thinks gossip is harmless to friendship.', '{"question":"What does Proverbs 16:28 say a gossip does?","wrong_answer":"Brings friends closer","correct_answer":"Separates close friends"}'::jsonb, 'Sharing news feels like closeness.', 'Offer "Brings friends closer" beside "Separates close friends" and ask the child to choose.', 'Read Proverbs 16:28: a gossip separates close friends. Act out a rumour spreading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.FRIENDSHIP_FORMATION.FRIENDSHIP.M_C6_FRI_WISE_FOOL', 'CRES.G6.CHRIST.FRIENDSHIP_FORMATION.FRIENDSHIP', 'Reverses Proverbs 13:20, thinking walking with fools makes one wise.', '{"question":"What does Proverbs 13:20 say happens to one who walks with the wise?","wrong_answer":"They suffer harm","correct_answer":"They become wise"}'::jsonb, 'Two halves of the proverb are learnt together and swap.', 'Offer "They suffer harm" beside "They become wise" and ask the child to choose.', 'Read the verse in two halves and draw two paths: wise friends, wise; foolish friends, harm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_BIBLE.M_SEX6_BODY', 'CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_BIBLE', 'Thinks the body is only one''s own to use as one pleases.', '{"question":"Why should we respect our bodies (1 Corinthians 6:19)?","wrong_answer":"We can do what we like with them","correct_answer":"The body is the temple of the Holy Spirit"}'::jsonb, 'The child hears "my body, my choice" from media and stops there.', 'Offer "We can do what we like with them" beside "The body is the temple of the Holy Spirit" and ask the child to choose.', 'Read 1 Corinthians 6:19-20: a temple, bought at a price. Ask what we do in a temple.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_BIBLE.M_SEX6_TEMPT', 'CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_BIBLE', 'Thinks being tempted is itself a sin.', '{"question":"When does temptation lead to sin (James 1:14-15)?","wrong_answer":"The moment a person is tempted","correct_answer":"When desire is allowed to grow and is acted on"}'::jsonb, 'The child feels guilty for any wrong thought and thinks it is already sin.', 'Offer "The moment a person is tempted" beside "When desire is allowed to grow and is acted on" and ask the child to choose.', 'Read James 1:14-15 in steps: desire, conceived, sin. Jesus was tempted and did not sin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_BIBLE.M_SEX6_SECRET', 'CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_BIBLE', 'Thinks a problem should be kept secret from adults.', '{"question":"A child is troubled about growing up. What is wise?","wrong_answer":"Hide it from every adult","correct_answer":"Talk to a parent or trusted adult"}'::jsonb, 'Shame about the body makes the child hide worries.', 'Offer "Hide it from every adult" beside "Talk to a parent or trusted adult" and ask the child to choose.', 'Name trusted adults; say that asking is wise and normal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_SKILLS.M_SEX6_PRESSURE', 'CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_SKILLS', 'Thinks peer pressure should be obeyed.', '{"question":"A friend pushes you to do wrong. What do you do?","wrong_answer":"Give in so as to stay in the group","correct_answer":"Say no firmly and walk away"}'::jsonb, 'Belonging to a group matters a lot at this age.', 'Offer "Give in so as to stay in the group" beside "Say no firmly and walk away" and ask the child to choose.', 'Practise firm refusals: "No, I don''t do that." Then walk away. Name friends who support you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_SKILLS.M_SEX6_GIFT', 'CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_SKILLS', 'Thinks gifts for favours are harmless.', '{"question":"An older person offers gifts in return for favours. What is right?","wrong_answer":"Accept, it is only a gift","correct_answer":"Refuse and tell a trusted adult"}'::jsonb, 'Gifts feel kind, and the child does not see the trap.', 'Offer "Accept, it is only a gift" beside "Refuse and tell a trusted adult" and ask the child to choose.', 'Say: gifts in return for favours are a warning sign. Refuse and tell a trusted adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_SKILLS.M_SEX6_CAUSE', 'CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_SKILLS', 'Names being busy with school and sport as a cause of irresponsible behaviour, instead of peer pressure and too little guidance.', '{"question":"Which can lead a young person into irresponsible behaviour?","wrong_answer":"Staying busy with school and sport","correct_answer":"Peer pressure and too little guidance"}'::jsonb, 'The child does not yet see what leads young people astray.', 'Offer "Staying busy with school and sport" beside "Peer pressure and too little guidance" and ask the child to choose.', 'List real causes: peer pressure, idleness, media, too little guidance, drugs. Busy with good things protects.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_BIBLE.M_C6_SEX_MEDIA_NORMAL', 'CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_BIBLE', 'Thinks what films and music show about relationships is how everyone lives, so it must be right.', '{"question":"Films show young people in sexual relationships as normal. What does the Bible teach?","wrong_answer":"It is normal and right","correct_answer":"Keep sex for marriage and honour God with your body"}'::jsonb, 'Media are the loudest voice the child hears on this.', 'Offer "It is normal and right" beside "Keep sex for marriage and honour God with your body" and ask the child to choose.', 'Contrast what a film shows with 1 Corinthians 6:18-20. Ask who made the film and why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_SKILLS.M_C6_SEX_CANNOT_SAY_NO', 'CRES.G6.CHRIST.HUMAN_SEXUALITY_7_LESSON.SEXUALITY_SKILLS', 'Thinks a young person cannot refuse once someone older or popular insists.', '{"question":"Someone older insists you go alone with them to their house. Can you refuse?","wrong_answer":"No, I must obey an older person","correct_answer":"Yes: say no, go away and tell a trusted adult"}'::jsonb, 'Children are taught to obey elders and feel they have no right to refuse.', 'Offer "No, I must obey an older person" beside "Yes: say no, go away and tell a trusted adult" and ask the child to choose.', 'Practise assertiveness: a child may always refuse what is wrong or unsafe, even from an adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE.M_SAN6_OWN', 'CRES.G6.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE', 'Thinks a life is one''s own to take or harm.', '{"question":"Where does life come from?","wrong_answer":"From ourselves alone","correct_answer":"It is a gift from God"}'::jsonb, 'The child thinks what is mine is mine to use.', 'Offer "From ourselves alone" beside "It is a gift from God" and ask the child to choose.', 'Read Genesis 2:7: God breathed life into the man. Life is a gift we care for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE.M_SAN6_MOB', 'CRES.G6.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE', 'Thinks mob justice is acceptable.', '{"question":"A crowd catches a thief and wants to beat him. What is right?","wrong_answer":"Join in, he deserves it","correct_answer":"Hand him to the police, since life must be protected"}'::jsonb, 'The child has seen crowds punish thieves and thinks it is justice.', 'Offer "Join in, he deserves it" beside "Hand him to the police, since life must be protected" and ask the child to choose.', 'Ask: who has the right to judge? The police and courts. Every life, even a thief''s, is sacred.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE.M_SAN6_ANGER', 'CRES.G6.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE', 'Thinks only physical killing matters, not hatred.', '{"question":"What does Jesus teach about anger (Matthew 5:21-22)?","wrong_answer":"Anger is harmless","correct_answer":"Anger and hatred also harm and must be dealt with"}'::jsonb, 'The child thinks only acts count, not feelings.', 'Offer "Anger is harmless" beside "Anger and hatred also harm and must be dealt with" and ask the child to choose.', 'Read Matthew 5:21-22: Jesus names anger and insults too. Deal with anger early.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE.M_C6_SAN_SELF_HARM', 'CRES.G6.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE', 'Thinks harming one''s own body by drugs or reckless dares does not break the sanctity of life.', '{"question":"Does taking drugs or reckless dares go against the sacredness of life?","wrong_answer":"No, it is only my own life","correct_answer":"Yes: my life is God''s gift too, so I protect it"}'::jsonb, 'The child thinks sanctity of life is only about not hurting others.', 'Offer "No, it is only my own life" beside "Yes: my life is God''s gift too, so I protect it" and ask the child to choose.', 'Read 1 Corinthians 6:19-20: your body is not your own. Protect your own life as well as others''.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE.M_DRU6_MEDICINE', 'CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE', 'Thinks all medicine is drug abuse.', '{"question":"Which is drug abuse?","wrong_answer":"Taking medicine as the doctor directs","correct_answer":"Sniffing glue"}'::jsonb, 'The word drug is used for medicine and for abuse.', 'Offer "Taking medicine as the doctor directs" beside "Sniffing glue" and ask the child to choose.', 'Sort cards: medicine as the doctor directs (use); glue, bhang, alcohol for a high (abuse).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE.M_DRU6_TRY', 'CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE', 'Thinks trying once is harmless.', '{"question":"What is true of trying a harmful drug once?","wrong_answer":"It is harmless","correct_answer":"It can start an addiction"}'::jsonb, 'The child thinks harm comes only from many times.', 'Offer "It is harmless" beside "It can start an addiction" and ask the child to choose.', 'Explain addiction simply: the body asks for more. Many addicts began with "just once".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE.M_DRU6_VERSE', 'CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE', 'Thinks Ephesians 5:18 says "drink wine with joy", instead of "do not get drunk on wine, but be filled with the Spirit".', '{"question":"What does Ephesians 5:18 say?","wrong_answer":"Drink wine with joy","correct_answer":"Do not get drunk on wine, but be filled with the Spirit"}'::jsonb, 'The child has seen wine at weddings in the Bible and thinks drinking is praised.', 'Offer "Drink wine with joy" beside "Do not get drunk on wine, but be filled with the Spirit" and ask the child to choose.', 'Read Ephesians 5:18 and Hosea 4:11: do not get drunk; wine takes away understanding.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_PREVENT.M_DRP6_AGENCY', 'CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_PREVENT', 'Names the examinations council instead of NACADA as the body that campaigns against drug abuse.', '{"question":"Which authority runs campaigns against alcohol and drug abuse?","wrong_answer":"The National Examinations Council","correct_answer":"NACADA"}'::jsonb, 'The child knows national bodies like KNEC from school and picks one.', 'Offer "The National Examinations Council" beside "NACADA" and ask the child to choose.', 'Write NACADA in full: National Authority for the Campaign Against Alcohol and Drug Abuse. Add the police.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_PREVENT.M_DRP6_HIDE', 'CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_PREVENT', 'Thinks a person who abuses drugs should be hidden or abandoned.', '{"question":"A friend is addicted to drugs. What is the Christian response?","wrong_answer":"Avoid him and tell no one","correct_answer":"Support him and help him find a counsellor"}'::jsonb, 'Shame and fear make the child want to avoid an addicted friend.', 'Offer "Avoid him and tell no one" beside "Support him and help him find a counsellor" and ask the child to choose.', 'Read Galatians 6:2: carry each other''s burdens. Name counsellors, pastors and rehabilitation centres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_PREVENT.M_DRP6_SAYNO', 'CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_PREVENT', 'Thinks saying no is rude or weak.', '{"question":"A friend offers you cigarettes. What do you do?","wrong_answer":"Accept so as not to look weak","correct_answer":"Refuse firmly, walk away and tell an adult"}'::jsonb, 'Saying no feels unfriendly and risky.', 'Offer "Accept so as not to look weak" beside "Refuse firmly, walk away and tell an adult" and ask the child to choose.', 'Practise three ways to say no and walk away. Strong people say no.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE.M_C6_DRU_ADULTS_FINE', 'CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_BIBLE', 'Thinks getting drunk is wrong only for children and fine for adults.', '{"question":"According to Ephesians 5:18, is getting drunk right for adults?","wrong_answer":"Yes, adults may get drunk","correct_answer":"No: the verse says do not get drunk, for everyone"}'::jsonb, 'The child sees adults drinking and links the rule only with age.', 'Offer "Yes, adults may get drunk" beside "No: the verse says do not get drunk, for everyone" and ask the child to choose.', 'Read Ephesians 5:18 aloud: it is written to all believers. Name the harm drunkenness does to families.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_PREVENT.M_C6_DRP_POLICE_ONLY', 'CRES.G6.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS_PREVENT', 'Thinks only the police can fight drug abuse, so ordinary Christians have no part.', '{"question":"Who can help fight drug abuse?","wrong_answer":"Only the police","correct_answer":"Families, churches, schools, NACADA, the police and young people themselves"}'::jsonb, 'Arrests are what the child sees on the news.', 'Offer "Only the police" beside "Families, churches, schools, NACADA, the police and young people themselves" and ask the child to choose.', 'Make a circle of helpers: family, church, school, NACADA, police, friends. Ask what each does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
